import java.util.*;

class Solution {
  private final Map<Integer, Integer> count = new HashMap<>();
  private int best;

  public int[] findFrequentTreeSum(TreeNode root) {
    sum(root);
    List<Integer> res = new ArrayList<>();
    for (Map.Entry<Integer, Integer> e : count.entrySet()) if (e.getValue() == best) res.add(e.getKey());
    return res.stream().mapToInt(Integer::intValue).toArray();
  }

  private int sum(TreeNode node) {
    if (node == null) return 0;
    int s = node.val + sum(node.left) + sum(node.right);
    best = Math.max(best, count.merge(s, 1, Integer::sum));
    return s;
  }
}
